package com.onurkat.reclazz.e2e;

import com.onurkat.reclazz.bootstrap.*;
import com.onurkat.reclazz.config.AgentConfig;
import com.onurkat.reclazz.reload.*;
import com.onurkat.reclazz.transform.*;
import java.lang.invoke.*;
import java.lang.ref.WeakReference;
import org.objectweb.asm.*;
import java.lang.reflect.*;
import java.nio.file.Path;
import java.util.*;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

/** Real generated bytecode and VM roots; full S physical admission remains a separate gate. */
class RecordGeneratedCompanionTest {
    @TempDir Path tmp;
    @Test void generatedBodiesConstructLogicalComponentsAndKeepPreparationPrivate()throws Exception {
        var harness=new RecordComponentMetadataTest();harness.tmp=tmp;
        harness.runProbe(Probe.class,"RECORD_GENERATED_COMPANION_OK");
    }
    public static class Probe extends TransformTestBase {
        private static int checks;
        private static void check(boolean ok,String message){if(!ok)throw new AssertionError(message);checks++;}
        private static WeakReference<ClassLoader> invokeRetiredInDisposableCaller(Constructor<?> retired)throws Throwable {
            var writer=new ClassWriter(0);writer.visit(Opcodes.V17,Opcodes.ACC_PUBLIC,"com/example/RetiredConstructorCaller",null,"java/lang/Object",null);
            var body=writer.visitMethod(Opcodes.ACC_PUBLIC|Opcodes.ACC_STATIC,"call","(Ljava/lang/reflect/Constructor;[Ljava/lang/Object;)Ljava/lang/Object;",null,null);
            body.visitCode();body.visitVarInsn(Opcodes.ALOAD,0);body.visitVarInsn(Opcodes.ALOAD,1);
            body.visitMethodInsn(Opcodes.INVOKEVIRTUAL,"java/lang/reflect/Constructor","newInstance","([Ljava/lang/Object;)Ljava/lang/Object;",false);
            body.visitInsn(Opcodes.ARETURN);body.visitMaxs(2,2);body.visitEnd();writer.visitEnd();byte[] bytes=writer.toByteArray();
            class CallerLoader extends ClassLoader {
                CallerLoader(){super(retired.getDeclaringClass().getClassLoader());}
                Class<?> define(){return defineClass("com.example.RetiredConstructorCaller",bytes,0,bytes.length);}
            }
            var loader=new CallerLoader();Class<?> caller=loader.define();
            try {caller.getMethod("call",Constructor.class,Object[].class).invoke(null,retired,new Object[]{9});throw new AssertionError("retired descriptor constructed from a disposable caller");}
            catch(InvocationTargetException outer){check(outer.getCause() instanceof InvocationTargetException inner&&inner.getCause() instanceof NoSuchMethodError,"disposable caller reaches the real retired-constructor failure");}
            return new WeakReference<>(loader);
        }
        public static void main(String[] args)throws Throwable {
            String name="com/example/GeneratedRecord";
            var oldClasses=compile(new SourceFile("com.example.GeneratedRecord","""
                package com.example;
                public record GeneratedRecord(int value,String retired) implements DefaultLabel {
                    private GeneratedRecord(int value){this(value,"private-old");}
                    public String label(){return "old:"+value;}
                    public int[] values(){return new int[]{value};}
                    public String valueOf(String text){return text;}
                    @Override public String inherited(){return "overridden";}
                }
                sealed interface DefaultLabel permits GeneratedRecord {default String inherited(){return "default";}}
                """));
            byte[] old=oldClasses.get(name);
            byte[] next=compile(new SourceFile("com.example.GeneratedRecord","""
                package com.example;
                public record GeneratedRecord(int value,String added) implements DefaultLabel {
                    public GeneratedRecord {if(value<0)throw new IllegalArgumentException("negative");}
                    public GeneratedRecord(int value){this(value+1,"aux");}
                    public String label(){return "new:"+value+":"+added;}
                    public int[] values(){return new int[]{value+100};}
                }
                sealed interface DefaultLabel permits GeneratedRecord {default String inherited(){return "default";}}
                """)).get(name);
            var context=new TransformContext();context.addWatched(name);
            var transformer=new ReclazzTransformer(context,AgentConfig.parse(null));
            class Loader extends ClassLoader {
                Loader(){super(Probe.class.getClassLoader());}
                @Override protected Class<?> findClass(String binary)throws ClassNotFoundException {
                    byte[] bytes=oldClasses.get(binary.replace('.','/'));
                    if(bytes==null)throw new ClassNotFoundException(binary);
                    return defineClass(binary,bytes,0,bytes.length);
                }
                Class<?> define()throws Exception {byte[] bytes=transformer.transform(this,name,null,null,old);return defineClass(name.replace('/','.'),bytes,0,bytes.length);}
            }
            Class<?> owner=new Loader().define();
            check(owner.getInterfaces()[0].isSealed(),"real source record implements its sealed interface");
            var field=owner.getDeclaredField(InjectedNames.LOOKUP_FIELD);field.setAccessible(true);
            var lookup=(MethodHandles.Lookup)field.get(null);
            Constructor<?> physicalCanonical=owner.getConstructor(int.class,String.class);
            Constructor<?> privatePhysical=owner.getDeclaredConstructor(int.class);
            try {privatePhysical.newInstance(1);throw new AssertionError("private physical constructor access bypassed before S");}
            catch(IllegalAccessException expected){checks++;}
            try {MethodHandles.publicLookup().findConstructor(owner,MethodType.methodType(void.class,int.class));throw new AssertionError("public lookup found private constructor before S");}
            catch(IllegalAccessException expected){checks++;}
            try {MethodHandles.publicLookup().unreflectConstructor(privatePhysical);throw new AssertionError("public lookup unreflected private constructor before S");}
            catch(IllegalAccessException expected){checks++;}
            MethodHandle physicalFactory=lookup.findConstructor(owner,MethodType.methodType(void.class,int.class,String.class));
            MethodHandle unreflectedFactory=lookup.unreflectConstructor(physicalCanonical);
            Object previous=physicalCanonical.newInstance(5,"retained");
            Method held=owner.getMethod("label"),retired=owner.getMethod("retired"),inherited=owner.getMethod("inherited");check(held.invoke(previous).equals("old:5"),"old transformed body starts live");
            Method heldValues=owner.getMethod("values"),heldValueOf=owner.getMethod("valueOf",String.class);
            check(((int[])heldValues.invoke(previous))[0]==5&&heldValueOf.invoke(previous,"before").equals("before"),"record methods named like enum helpers start as real bodies");
            LookupCapture.trust(Probe.class);LookupCapture.trust(RecordCompanion.class);LookupCapture.trust(RecordMemberSnapshot.class);LookupCapture.trust(ProtectedCallResolver.class);
            LookupCapture.store(owner,lookup);LookupCapture.seal();
            var built=RecordCompanion.prepare(owner,lookup,next,context,1);
            check(built.lookup().lookupClass().isHidden(),"real hidden executable companion");
            check(held.invoke(previous).equals("old:5"),"compiling a companion does not publish bodies");
            check(owner.getRecordComponents()[1].getName().equals("retired"),"compiling a companion does not publish metadata");
            var slot=RecordSchema.slot(owner);
            try(var pending=slot.prepareVirtual(built.snapshot().members())) {
                pending.stageDispatch(owner,built.snapshot().targets());
                check(held.invoke(previous).equals("old:5"),"staged body remains old before CAS");
                check(pending.commit(),"generated snapshot activates");
            }
            check(held.invoke(previous).equals("new:5:null"),"old trampoline reaches generated body with default new component");
            check(owner.getRecordComponents()[1].getName().equals("added"),"logical component replaces retired one");
            check(((int[])heldValues.invoke(previous))[0]==105,"held record values() reaches new array body");
            try{heldValueOf.invoke(previous,"old");throw new AssertionError("retired record valueOf still executes");}
            catch(InvocationTargetException expected){check(expected.getCause() instanceof NoSuchMethodError,"held record valueOf retires through owned removal target");}
            try {retired.invoke(previous);throw new AssertionError("retired physical accessor still serves the old body");}
            catch(InvocationTargetException expected){check(expected.getCause() instanceof NoSuchMethodError,"retired physical accessor reaches an owned removal stub");}

            check(inherited.invoke(previous).equals("default"),"removed override reaches the inherited default instead of a stale body or thrower");
            Object made=owner.getConstructor(int.class,String.class).newInstance(7,"fresh");
            try {MemberForge.newRecordInstance(physicalCanonical,new Object[]{12,"bypass"});throw new AssertionError("public constructor bridge bypassed the JDK access check");}
            catch(SecurityException expected){checks++;}
            Object physicalMade=physicalCanonical.newInstance(12,"held");
            check(Objects.equals(owner.getMethod("added").invoke(physicalMade),"held"),"constructor retained before S follows the logical initializer");
            Object factoryMade=physicalFactory.invokeWithArguments(13,"factory");
            check(Objects.equals(owner.getMethod("added").invoke(factoryMade),"factory"),"findConstructor handle retained before S follows the logical initializer");
            Object unreflectedMade=unreflectedFactory.invokeWithArguments(14,"unreflected");
            check(Objects.equals(owner.getMethod("added").invoke(unreflectedMade),"unreflected"),"unreflected constructor retained before S follows the logical initializer");

            check(owner.getMethod("value").invoke(made).equals(7),"generated canonical writes compatible physical value");
            check(owner.getMethod("added").invoke(made).equals("fresh"),"generated canonical writes new component storage");
            check(owner.getMethod("label").invoke(made).equals("new:7:fresh"),"generated body reads new storage");
            check(owner.getMethod("toString").invoke(made).equals("GeneratedRecord[value=7, added=fresh]"),"generated ObjectMethods use the logical schema");
            check(owner.getMethod("toString").invoke(previous).equals("GeneratedRecord[value=5, added=null]"),"old object keeps compatible value and new default");
            Object equal=owner.getConstructor(int.class,String.class).newInstance(7,"fresh");
            check((boolean)owner.getMethod("equals",Object.class).invoke(made,equal),"generated logical equality");
            check(owner.getMethod("hashCode").invoke(made).equals(owner.getMethod("hashCode").invoke(equal)),"generated logical hash consistency");
            try {privatePhysical.newInstance(1);throw new AssertionError("private held root bypassed the original JDK access check after S");}
            catch(IllegalAccessException expected){checks++;}
            privatePhysical.setAccessible(true);
            check(owner.getMethod("label").invoke(privatePhysical.newInstance(1)).equals("new:2:aux"),"explicit accessible override uses the current logical initializer");
            Object auxiliary=owner.getConstructor(int.class).newInstance(8);
            check(owner.getMethod("label").invoke(auxiliary).equals("new:9:aux"),"generated auxiliary delegates to canonical initializer");
            try {owner.getConstructor(int.class,String.class).newInstance(-1,"bad");throw new AssertionError("constructor validation missing");}
            catch(InvocationTargetException expected){check(expected.getCause() instanceof IllegalArgumentException,"generated constructor validation preserved");}
            Constructor<?> heldCanonical=owner.getConstructor(int.class,String.class);Method heldHash=owner.getMethod("hashCode");
            byte[] reordered=compile(new SourceFile("com.example.GeneratedRecord","""
                package com.example;
                public record GeneratedRecord(String added,int value) implements DefaultLabel {
                    public String label(){return "reordered:"+added+":"+value;}
                    @Override public String toString(){return "custom:"+added;}
                }
                sealed interface DefaultLabel permits GeneratedRecord {default String inherited(){return "default";}}
                """)).get(name);
            var second=RecordCompanion.prepare(owner,lookup,reordered,context,2);
            try(var pending=slot.prepareVirtual(second.snapshot().members())) {
                pending.stageDispatch(owner,second.snapshot().targets());
                check(held.invoke(made).equals("new:7:fresh"),"second preparation leaves the first generated body active");
            }
            check(held.invoke(made).equals("new:7:fresh"),"aborted generated preparation keeps the previous body");
            check(owner.getRecordComponents()[0].getName().equals("value"),"aborted generated preparation keeps the previous schema");
            try(var pending=slot.prepareVirtual(second.snapshot().members())) {
                pending.stageDispatch(owner,second.snapshot().targets());check(pending.commit(),"second generated snapshot activates");
            }
            check(held.invoke(made).equals("reordered:fresh:7"),"held trampoline follows second generated body");
            check(owner.getMethod("toString").invoke(made).equals("custom:fresh"),"custom ObjectMethods body survives the adapter");
            check(heldHash.invoke(made).equals("fresh".hashCode()*31+7),"held generated hash follows reordered component snapshot");
            Object reorderedNew=owner.getConstructor(String.class,int.class).newInstance("later",11);
            var callerLoader=invokeRetiredInDisposableCaller(privatePhysical);
            for(int i=0;i<80&&callerLoader.get()!=null;i++){System.gc();Thread.sleep(20);}
            check(callerLoader.get()==null,"retired constructor factory cache must not retain its disposable caller's VM backtrace");
            try {physicalCanonical.newInstance(15,"retired");throw new AssertionError("physical canonical retained before S still constructs retired descriptor");}
            catch(InvocationTargetException expected){check(expected.getCause() instanceof NoSuchMethodError,"pre-S physical constructor retires with the schema");}
            try {physicalFactory.invokeWithArguments(16,"retired");throw new AssertionError("pre-S constructor handle still constructs retired descriptor");}
            catch(NoSuchMethodError expected){checks++;}
            try {unreflectedFactory.invokeWithArguments(17,"retired");throw new AssertionError("pre-S unreflected constructor still constructs retired descriptor");}
            catch(NoSuchMethodError expected){checks++;}

            check(held.invoke(reorderedNew).equals("reordered:later:11"),"new reordered canonical uses generated initializer");
            try {heldCanonical.newInstance(8,"retired");throw new AssertionError("retired generated canonical still constructs");}
            catch(InvocationTargetException expected){check(expected.getCause() instanceof NoSuchMethodError,"held retired generated constructor is rejected");}
            System.out.println("RECORD_GENERATED_COMPANION_OK checks="+checks+" runtime="+Runtime.version()+" unsafeDeny="+Boolean.getBoolean("reclazz.record.unsafe.deny"));
        }
    }
}
